/* Generated by Trae Work */
/* 时间线：双轨事件列表 */
"use strict";
(function () {
  document.addEventListener("DOMContentLoaded", () => {
    const filter = document.getElementById("tl-filter");
    const list = document.getElementById("tl-list");

    function render(track) {
      const evs = SITE_DATA.timeline
        .filter(e => track === "all" || e.track === track)
        .sort((a, b) => String(a.date_start || "9999").localeCompare(String(b.date_start || "9999")));
      list.innerHTML = "";
      if (evs.length === 0) {
        list.innerHTML = `<div class="notice empty">该轨道暂无已收录时间事件。</div>`;
        return;
      }
      evs.forEach(e => {
        const dateText = e.date_start
          ? (e.date_end && e.date_end !== e.date_start ? `${e.date_start} ~ ${e.date_end}` : e.date_start)
          : "待官方公布";
        const d = h("div", { class: "tl-event" });
        d.innerHTML = `
          <div class="tl-date">${dateText}</div>
          <div class="tl-body">
            <h4>${badge(e.track)} ${e.event_name}${dateTypeBadge(e.date_type)}</h4>
            <div class="note">${e.note || ""}</div>
            <div class="src" style="margin-top:6px;">来源：<a href="${e.source_url}" target="_blank" rel="noopener">${e.source_url}</a></div>
          </div>`;
        list.appendChild(d);
      });
    }

    filter.addEventListener("click", ev => {
      const b = ev.target.closest("button[data-track]");
      if (!b) return;
      filter.querySelectorAll("button").forEach(x => x.classList.toggle("active", x === b));
      render(b.dataset.track);
    });
    filter.querySelector('[data-track="all"]').classList.add("active");
    render("all");
  });
})();
